/// Lockfree queue for transactions
///
/// Multiple producers, single consumer. Sumeragi must serialize transaction popping and guard
/// returns through one consumer path; producers may continue admitting transactions concurrently.
pub struct Queue {
    events_sender: EventsSender,
    /// Resolves lane/dataspace assignments for queued transactions.
    router: RwLock<Arc<dyn LaneRouter>>,
    /// Optional lane compliance engine.
    lane_compliance: RwLock<Option<Arc<crate::compliance::LaneComplianceEngine>>>,
    /// Cached lane catalog for routing/telemetry.
    lane_catalog: RwLock<Arc<LaneCatalog>>,
    /// Cached dataspace catalog for routing/telemetry.
    dataspace_catalog: RwLock<Arc<DataSpaceCatalog>>,
    /// Cached routing policy used by the active router.
    routing_policy: RwLock<LaneRoutingPolicy>,
    /// Whether the active router is the Nexus config router.
    routing_uses_config_router: RwLock<bool>,
    /// The queue for transactions
    tx_hashes: ArrayQueue<SignedTxHash>,
    /// Accepted transactions addressed by `Hash`.
    /// Stored behind `Arc` to avoid deep cloning heavy transactions
    /// (including instruction payloads) during queue operations.
    txs: DashMap<SignedTxHash, Arc<CheckedTransaction<'static>>>,
    /// Cached count of transactions tracked by `txs`.
    active_count: AtomicUsize,
    /// Durable reservation owners whose transaction payload has not yet been
    /// restored into `txs`.
    ///
    /// Each owner consumes one configured transaction slot and the minimum
    /// retained-byte charge until exact payload replay materializes it.
    missing_reservation_payload_count: AtomicUsize,
    /// Cached routing decision per transaction hash.
    routing_decisions: DashMap<SignedTxHash, RoutingDecision>,
    /// Cached full routing plan per transaction hash.
    routing_plans: DashMap<SignedTxHash, RoutingPlan>,
    /// Bounded claim index rebuilt from live V4 journal records during startup replay.
    durable_plan_claims: DashMap<SignedTxHash, QueuePlanDurableClaimIndexEntry>,
    /// Cached encoded length per queued transaction hash.
    tx_encoded_len: DashMap<SignedTxHash, usize>,
    /// Cached proposal gas cost per queued transaction hash.
    tx_gas_cost: DashMap<SignedTxHash, u64>,
    /// Local enqueue timestamp in milliseconds for tracked transactions.
    tx_enqueued_at_ms: DashMap<SignedTxHash, u64>,
    /// Local enqueue timestamp in milliseconds for hashes still waiting in `tx_hashes`.
    queued_tx_enqueued_at_ms: DashMap<SignedTxHash, u64>,
    /// Stable FIFO ordinal for every tracked transaction, including lane-owned reservations.
    fifo_order_by_hash: DashMap<SignedTxHash, LaneQueueFifoOrderV5>,
    /// Next FIFO ordinal allocated to a newly admitted transaction.
    next_fifo_ordinal: parking_lot::Mutex<u64>,
    /// FIFO enqueue-age index used to read the oldest queued transaction without scanning.
    /// Also serializes `tx_hashes` updates with this age index.
    queued_age_ring: parking_lot::Mutex<VecDeque<(SignedTxHash, u64)>>,
    /// Cached count of hashes still waiting in `tx_hashes`.
    queued_count: AtomicUsize,
    /// Optional local journal for replaying pending transactions with full routing plans.
    plan_journal: parking_lot::Mutex<Option<QueuePlanJournal>>,
    /// Lock-free publication bit for queue paths that only need to know whether plan durability is
    /// active. This prevents those paths from waiting on a journal fsync while holding the queue
    /// mutation lock.
    plan_journal_installed: AtomicBool,
    /// Serializes startup plan-journal installation without retaining either runtime lock across
    /// path repair and replay I/O.
    plan_journal_install_lock: parking_lot::Mutex<()>,
    /// Non-authorizing identity of the exact post-tombstone V4 startup replay publication.
    plan_journal_startup_replay_receipt:
        parking_lot::Mutex<Option<QueuePlanStartupReplayReceiptV1>>,
    /// Durable exact ownership of queue entries selected by independent lane ticks.
    lane_reservations: parking_lot::Mutex<LaneQueueReservationStore>,
    /// Reservation journal writer, intentionally separate from the in-memory owner indexes.
    ///
    /// Durable state machines are serialized by `lane_reservation_transition_lock`. Keeping the
    /// blocking writer behind its own mutex prevents queue readers from convoying behind fsync
    /// while they hold `push_remove_lock`.
    lane_reservation_journal: parking_lot::Mutex<Option<LaneQueueReservationJournal>>,
    /// Non-authorizing identity of the exact checked snapshot replay installed
    /// into the process-local Queue indexes.
    lane_reservation_snapshot_replay_receipt:
        parking_lot::Mutex<Option<LaneReservationSnapshotReplayReceipt>>,
    /// Live sponsor-program capacity holds keyed by signed transaction hash.
    fee_admission_reservations: parking_lot::Mutex<FeeAdmissionReservationStore>,
    /// Sticky process-lifetime fault after an ambiguous pending-plan journal boundary.
    plan_journal_durability_fault: AtomicBool,
    /// Sticky process-lifetime fault after an ambiguous reservation-journal durability boundary.
    lane_reservation_durability_fault: AtomicBool,
    /// Sticky process-lifetime fault when accepted work exposes internally inconsistent immutable
    /// routing or fee-admission identity. Expected catalog retirement evicts affected work instead.
    accepted_work_validation_fault: AtomicBool,
    /// Startup publication gate retained until V2 has classified every
    /// replayed reservation owner against one State/Kura evidence snapshot.
    ///
    /// QueuePlan replay may materialize quarantined payload bytes while this
    /// bit is set, but ordinary admission, gossip, and global/lane selection
    /// remain closed.
    lane_reservation_reconciliation_pending: AtomicBool,
    /// Exact queue hashes fenced by an in-construction global carrier candidate.
    global_selection_owners: parking_lot::Mutex<BTreeMap<SignedTxHash, u64>>,
    /// Monotonic, nonzero process-local global selection owner identity.
    next_global_selection_owner: AtomicU64,
    /// Hashes of transactions removed from `txs` but still present in `tx_hashes`
    removed_hashes: DashMap<SignedTxHash, ()>,
    /// Amount of transactions per user in the queue
    txs_per_user: DashMap<AccountId, usize>,
    /// Lock to synchronize push and remove operations
    push_remove_lock: parking_lot::Mutex<()>,
    /// Exact hashes whose journal transition is in progress without the queue mutation lock.
    durability_transitions: parking_lot::Mutex<HashSet<SignedTxHash>>,
    /// Wakes exact-hash removals after an off-lock durability transition publishes or rolls back.
    durability_transition_done: parking_lot::Condvar,
    /// Serializes reservation state machines before they acquire the queue mutation lock.
    ///
    /// A waiting reservation operation therefore cannot hold `push_remove_lock` while another
    /// operation is completing a storage barrier.
    lane_reservation_transition_lock: parking_lot::Mutex<()>,
    /// Deterministic test handoff between a durability precheck and its protected recheck.
    #[cfg(test)]
    durability_observer_lock_handoff:
        parking_lot::Mutex<Option<QueueDurabilityObserverLockHandoff>>,
    /// Deterministic test handoff after Nexus snapshots queue hashes but before it observes one.
    #[cfg(test)]
    nexus_revalidation_snapshot_handoff:
        parking_lot::Mutex<Option<QueueDurabilityObserverLockHandoff>>,
    /// One-shot append fault consumed by install-time reservation reconciliation tests.
    #[cfg(test)]
    install_reconciliation_append_fault:
        parking_lot::Mutex<Option<(usize, ReservationJournalAppendFault)>>,
    /// One-shot test crash boundary after durable Commit and plan retirement,
    /// before durable ForgetCommit removes the exact reservation owner.
    #[cfg(test)]
    hold_next_lane_reservation_commit_after_barrier: AtomicBool,
    /// One-shot test crash boundary after the V6 PlanTombstoned sync and
    /// before the matching Queue store publication.
    #[cfg(test)]
    hold_next_lane_reservation_commit_after_plan_marker: AtomicBool,
    /// Monotonic counter tagging test guards with their queue order.
    #[cfg(test)]
    guard_sequence: AtomicU64,
    /// Active guards holding queued transactions (used to avoid resyncing during in-flight reads).
    inflight_guards: AtomicUsize,
    /// Queue-pop calls between FIFO ownership and guard publication.
    selection_attempts: AtomicUsize,
    /// The maximum number of transactions in the queue
    capacity: NonZeroUsize,
    /// The maximum number of transactions in the queue per user. Used to apply throttling
    capacity_per_user: NonZeroUsize,
    /// Estimated maximum retained queue memory budget in bytes.
    max_retained_bytes: NonZeroU64,
    /// Estimated retained memory for transactions currently tracked by the queue.
    retained_bytes: AtomicU64,
    /// The time source used to check transaction against
    ///
    /// A mock time source is used in tests for determinism
    time_source: TimeSource,
    /// Length of time after which transactions are dropped.
    pub tx_time_to_live: Duration,
    /// Minimum interval between expired-transaction sweeps.
    expired_cull_interval: Duration,
    /// Maximum number of entries scanned per expired-transaction sweep.
    expired_cull_batch: NonZeroUsize,
    /// Last time (unix ms) we swept expired transactions.
    last_expired_cull_ms: AtomicU64,
    /// Round-robin ring of queued transaction hashes used for TTL sweeps.
    expiry_ring: parking_lot::Mutex<VecDeque<SignedTxHash>>,
    /// Membership guard for the expiry ring to prevent unbounded growth.
    expiry_ring_members: DashMap<SignedTxHash, ()>,
    /// Queue to gossip transactions
    tx_gossip: ArrayQueue<SignedTxHash>,
    /// Broadcast queue load so producers can observe backpressure.
    backpressure_tx: watch::Sender<BackpressureState>,
    /// Age budget in milliseconds used to mark queue pressure as latency-saturated.
    pressure_age_budget_ms: AtomicU64,
    /// Optional wake handle for the Sumeragi worker when new transactions are enqueued.
    sumeragi_wake: OnceLock<mpsc::SyncSender<()>>,
    /// Limits derived from Nexus configuration (TEU capacity, starvation bounds).
    nexus_limits: RwLock<QueueLimits>,
    /// Cached TEU metadata for queued transactions keyed by hash.
    #[cfg(feature = "telemetry")]
    tx_teu: DashMap<SignedTxHash, TxTeuInfo>,
    /// Aggregated TEU per lane for queued transactions.
    #[cfg(feature = "telemetry")]
    lane_teu_pending: DashMap<LaneId, PendingTeu>,
    /// Aggregated TEU per (lane, dataspace) for queued transactions.
    #[cfg(feature = "telemetry")]
    dataspace_teu_pending: DashMap<(LaneId, DataSpaceId), PendingTeu>,
    /// Governance manifest registry for Nexus lanes.
    lane_manifests: parking_lot::RwLock<LaneManifestRegistryHandle>,
    /// Privacy commitments advertised by lane manifests.
    lane_privacy_registry: parking_lot::RwLock<LanePrivacyRegistryHandle>,
    #[cfg(test)]
    vacant_entry_warnings: AtomicUsize,
}
impl fmt::Debug for Queue {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Queue")
            .field("capacity", &self.capacity)
            .field("capacity_per_user", &self.capacity_per_user)
            .field("max_retained_bytes", &self.max_retained_bytes)
            .field("tx_time_to_live", &self.tx_time_to_live)
            .field("expired_cull_interval", &self.expired_cull_interval)
            .field("expired_cull_batch", &self.expired_cull_batch)
            .field(
                "pressure_age_budget_ms",
                &self.pressure_age_budget_ms.load(Ordering::Relaxed),
            )
            .finish_non_exhaustive()
    }
}
/// Queue-side fence for one lane-retirement ownership observation.
///
/// The guard acquires `lane_reservation_transition_lock` before callers enter
/// the State lane-lifecycle fence. Its predicate then acquires only the queue
/// mutation and reservation-store locks, preserving the production order
/// `reservation transition -> lifecycle -> queue ownership`.
pub(crate) struct QueueLaneRetirementObserver<'queue> {
    queue: &'queue Queue,
    _reservation_transition_guard: parking_lot::MutexGuard<'queue, ()>,
}
impl QueueLaneRetirementObserver<'_> {
    /// Return whether the exact lane incarnation still owns or may receive
    /// queued work while the reservation-transition fence is held.
    #[must_use]
    pub(crate) fn lane_has_pending_work(
        &self,
        lane_id: LaneId,
        dataspace_id: DataSpaceId,
        lane_incarnation: Hash,
    ) -> bool {
        self.queue.lane_has_pending_work_under_retirement_observer(
            lane_id,
            dataspace_id,
            lane_incarnation,
        )
    }
}
const QUEUE_PRESSURE_MIN_AGE_BUDGET_MS: u64 = 2_000;
const QUEUE_PRESSURE_MAX_AGE_BUDGET_MS: u64 = 5_000;
/// Fixed queue/index overhead charged to every retained transaction.
///
/// Canonical bytes are charged separately with a conservative expansion factor so small
/// transactions do not each consume an arbitrary 128 KiB while large decoded payloads cannot
/// evade the retained-memory budget.
const TX_RETAINED_OVERHEAD_BYTES: u64 = 2 * 1024;
/// Conservative encoded-to-retained expansion for decoded transaction payloads and canonical
/// bytes kept across queue indexes.
const TX_RETAINED_DECODE_EXPANSION_FACTOR: u64 = 8;
/// Snapshot of queue pressure used by Torii admission and status reporting.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct QueuePressureSnapshot {
    /// Number of transactions tracked by the queue (queued, in-flight, or durably owned while
    /// awaiting exact payload replay).
    pub tracked_tx_count: usize,
    /// Number of transactions still waiting in the queue.
    pub queued_tx_count: usize,
    /// Maximum queue capacity configured for the peer.
    pub capacity: NonZeroUsize,
    /// Estimated retained bytes for all transactions and payload-less durable owners.
    pub retained_bytes: u64,
    /// Configured maximum estimated retained bytes for the queue.
    pub max_retained_bytes: NonZeroU64,
    /// Age in milliseconds of the oldest queue-resident transaction's local queue residence.
    pub oldest_queued_tx_age_ms: u64,
    /// Whether the queue saturated because the tracked count hit capacity.
    pub saturated_by_count: bool,
    /// Whether the queue saturated because the retained-byte budget is exhausted.
    pub saturated_by_bytes: bool,
    /// Whether the queue saturated because the oldest queued age exceeded the budget.
    pub saturated_by_age: bool,
}
impl QueuePressureSnapshot {
    /// Whether any saturation signal is active.
    #[must_use]
    pub const fn is_saturated(self) -> bool {
        self.saturated_by_count || self.saturated_by_bytes || self.saturated_by_age
    }
    /// Convert the richer pressure snapshot into the coarse backpressure state.
    ///
    /// Coarse backpressure gates admission and consensus pacing. Keep it tied to
    /// count/byte capacity saturation; age pressure stays available through the
    /// richer snapshot for status reporting and diagnostics.
    #[must_use]
    pub const fn into_backpressure(self) -> BackpressureState {
        if self.saturated_by_count || self.saturated_by_bytes {
            BackpressureState::Saturated {
                queued: self.queued_tx_count,
                capacity: self.capacity,
            }
        } else {
            BackpressureState::Healthy {
                queued: self.queued_tx_count,
                capacity: self.capacity,
            }
        }
    }
}
/// Snapshot of queue occupancy used to coordinate backpressure across Torii,
/// the gossiper, and consensus.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum BackpressureState {
    /// Queue has room for new transactions.
    Healthy {
        /// Number of transactions still waiting in the queue.
        queued: usize,
        /// Maximum queue capacity configured for the peer.
        capacity: NonZeroUsize,
    },
    /// Queue reached capacity; callers should defer submissions.
    Saturated {
        /// Number of transactions still waiting in the queue when saturation triggered.
        queued: usize,
        /// Maximum queue capacity configured for the peer.
        capacity: NonZeroUsize,
    },
}
impl BackpressureState {
    #[must_use]
    /// Whether the queue snapshot represents a saturated state.
    pub const fn is_saturated(self) -> bool {
        matches!(self, Self::Saturated { .. })
    }
    #[must_use]
    /// Number of transactions still waiting in the queue in the snapshot.
    pub const fn queued(self) -> usize {
        match self {
            Self::Healthy { queued, .. } | Self::Saturated { queued, .. } => queued,
        }
    }
    #[must_use]
    /// Queue capacity recorded in the snapshot.
    pub const fn capacity(self) -> NonZeroUsize {
        match self {
            Self::Healthy { capacity, .. } | Self::Saturated { capacity, .. } => capacity,
        }
    }
}
impl Default for BackpressureState {
    fn default() -> Self {
        Self::Healthy {
            queued: 0,
            capacity: NonZeroUsize::new(1).expect("capacity must be non-zero"),
        }
    }
}
